import 'package:flutter/material.dart';
import '../../core/api/aaspass_api.dart';
import '../../core/theme/app_theme.dart';

class AddressesScreen extends StatefulWidget{const AddressesScreen({super.key});@override State<AddressesScreen> createState()=>_AddressesScreenState();}
class _AddressesScreenState extends State<AddressesScreen>{List<Map<String,dynamic>> addresses=[];bool loading=true;@override void initState(){super.initState();_load();}Future<void> _load()async{try{final list=await AasPassApi.instance.addresses();if (mounted) { setState(() { addresses = list; loading = false; }); }}catch(_){if(mounted)setState(()=>loading=false);}}Future<void> _addAddress()async{final line=TextEditingController(),city=TextEditingController(text:'Lucknow'),pin=TextEditingController(text:'226010');final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Add address',style:TextStyle(fontWeight:FontWeight.w900)),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:line,maxLines:2,decoration:const InputDecoration(labelText:'House / street / landmark')),const SizedBox(height:10),Row(children:[Expanded(child:TextField(controller:city,decoration:const InputDecoration(labelText:'City'))),const SizedBox(width:8),Expanded(child:TextField(controller:pin,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'PIN')))])]),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Save'))]));if(ok==true){try{await AasPassApi.instance.createAddress({'label':'Home','line1':line.text.trim(),'city':city.text.trim(),'state':'Uttar Pradesh','postalCode':pin.text.trim(),'isDefault':addresses.isEmpty});await _load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Could not save address: $e')));}}line.dispose();city.dispose();pin.dispose();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Saved addresses',style:TextStyle(fontWeight:FontWeight.w900))),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(16),children:[if(addresses.isEmpty)const Padding(padding:EdgeInsets.all(24),child:Column(children:[Icon(Icons.home_work_outlined,color:AppTokens.green,size:34),SizedBox(height:8),Text('No saved addresses yet',style:TextStyle(fontWeight:FontWeight.w900)),SizedBox(height:4),Text('Add an address for faster checkout.',textAlign:TextAlign.center,style:TextStyle(color:AppTokens.muted))])) else ...addresses.map((a)=>Container(margin:const EdgeInsets.only(bottom:9),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18),border:Border.all(color:AppTokens.border)),child:Row(children:[const Icon(Icons.home_rounded,color:AppTokens.green),const SizedBox(width:10),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${a['label']??'Address'}',style:const TextStyle(fontWeight:FontWeight.w900)),Text('${a['line1']??''}, ${a['city']??''} - ${a['postal_code']??''}',style:const TextStyle(color:AppTokens.muted))])),if(a['is_default']==true)const Chip(label:Text('Default'))]))),const SizedBox(height:8),FilledButton.icon(onPressed:_addAddress,icon:const Icon(Icons.add),label:const Text('Add new address'))])));
}
